    int n = (int) in.nval;
    int ans = 0;
    int[] A = new int[n];
    for (int i = 0; i < n; i++) {
        in.nextToken();
        A[i] = (int) in.nval;
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (isPerfectSquare(A[i] * A[j])) {
                ans++;
            }
        }
    }
    pw.println(ans);
    pw.flush();
    pw.close();
}

private static boolean isPerfectSquare(int x) {
    if (x < 0) return false;
    int s = (int) Math.sqrt(x);
    return s * s == x;
}

