            while (num % k == 0) {
                num /= k;
            }
        }
        ans += count.getOrDefault(num, 0) + cnt0;
        count.put(num, count.getOrDefault(num, 0) + 1);
    }
    pw.println(ans);
    pw.flush();
    pw.close();
}

